import { readFileSync } from 'node:fs';
import { createMDX } from 'fumadocs-mdx/next';

// Every moved docs page: old URL (and its .md twin) to the new URL. Generated by scripts/docs-skeleton.mjs.
const moved = JSON.parse(readFileSync(new URL('./content/docs-redirects.json', import.meta.url), 'utf8'));
const movedTo = (old) => moved.find((entry) => entry.source === old)?.destination ?? old;

const withMDX = createMDX();

/** @type {import('next').NextConfig} */
const config = {
  reactStrictMode: true,
  // the app runs COMPILED here, matching what the unit-compiled/browser-compiled projects test
  reactCompiler: true,
  // The perf scripts build two variants side by side and compare them.
  ...(process.env.GRIDCN_DIST_DIR ? { distDir: process.env.GRIDCN_DIST_DIR } : {}),
  // fumadocs LLMs integration: /docs/<page>.md serves the page as raw markdown for AI agents.
  async redirects() {
    return [
      { source: "/docs/windowing", destination: movedTo("/docs/virtualization"), permanent: true },
      { source: "/docs/recipes/data-fetching/server-side-sort-filter", destination: movedTo("/docs/recipes/data-fetching/server-side"), permanent: true },
      ...moved.map((entry) => ({ ...entry, permanent: true })),
    ];
  },
  async rewrites() {
    return [
      {
        source: '/docs/:path*.md',
        destination: '/llms.mdx/docs/:path*',
      },
    ];
  },
};

export default withMDX(config);
